// Builds examples/index.ts: a map from example file name to its component.
import { readdirSync, writeFileSync } from "node:fs"

const files = readdirSync("examples")
  .filter((f) => f.endsWith(".tsx") && f !== "index.tsx")
  .map((f) => f.slice(0, -4))
  .sort()

const ident = (name) =>
  name.replace(/(^|-)([a-z0-9])/g, (_, __, c) => c.toUpperCase()).replace(/^[0-9]/, "_$&")

const lines = [
  "// Generated by scripts/gen-examples.mjs — do not edit by hand.",
  'import type { ComponentType } from "react"',
  "",
  ...files.map((f) => `import ${ident(f)} from "./${f}"`),
  "",
  "export const examples: Record<string, ComponentType> = {",
  ...files.map((f) => `  "${f}": ${ident(f)},`),
  "}",
  "",
]
writeFileSync("examples/index.ts", lines.join("\n"))
console.log(`examples: ${files.length}`)
